create or replace function public.update_developer_agency_settings_rc1(p_agency_id uuid,p_name text,p_logo_url text,p_website text,p_public_phone text,p_business_address text,p_description text,p_service_radius_miles numeric,p_settings jsonb) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501'; end if; if not exists(select 1 from public.agencies where id=p_agency_id) then raise exception 'AGENCY_NOT_FOUND'; end if; if nullif(trim(p_name),'') is null then raise exception 'COMPANY_NAME_REQUIRED'; end if; if p_service_radius_miles is null or p_service_radius_miles<1 or p_service_radius_miles>500 then raise exception 'INVALID_SERVICE_RADIUS'; end if; update public.agencies set name=trim(p_name),logo_url=nullif(trim(p_logo_url),''),website=nullif(trim(p_website),''),public_phone=nullif(trim(p_public_phone),''),business_address=nullif(trim(p_business_address),''),description=nullif(trim(p_description),''),service_radius_miles=p_service_radius_miles,settings=coalesce(p_settings,'{}'::jsonb),updated_at=now() where id=p_agency_id; return public.get_developer_agency_settings_rc1(p_agency_id); end; $$;
revoke all on function public.update_developer_agency_settings_rc1(uuid,text,text,text,text,text,text,numeric,jsonb) from public,anon;
grant execute on function public.update_developer_agency_settings_rc1(uuid,text,text,text,text,text,text,numeric,jsonb) to authenticated,service_role;
